#!/usr/bin/env bash
# Delete the cluster. One command, and it takes everything with it.
#
#   bash scripts/down.sh            # delete the cluster, keep .state/
#   bash scripts/down.sh --purge    # …and the generated credentials/kubeconfig
#   bash scripts/down.sh --stop     # stop the containers, keep the cluster
#
# There is nothing to preserve: the store is an emptyDir, postgres runs without
# a PVC, and every credential is regenerated by the next up.sh. `--purge` exists
# only so a fresh run is provably fresh.
#
# It touches nothing outside its own cluster: the dev stack's compose project,
# its ports (3000/8081/8082/8180/15432/9000/9001/8010) and any tunnel are
# untouched, because none of them is a k3d resource.
set -euo pipefail
. "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

PURGE=0; STOP=0
for arg in "$@"; do
    case "$arg" in
        --purge) PURGE=1 ;;
        --stop) STOP=1 ;;
        *) die "unknown flag $arg" ;;
    esac
done

if ! cluster_exists; then
    ok "cluster '$CLUSTER' is already gone"
else
    if [ "$STOP" = 1 ]; then
        step "stopping cluster '$CLUSTER'"
        k3d cluster stop "$CLUSTER" >/dev/null
        ok "stopped (k3d cluster start $CLUSTER to resume)"
        exit 0
    fi
    step "deleting cluster '$CLUSTER'"
    k3d cluster delete "$CLUSTER" >/dev/null
    ok "cluster, its network and its volumes are gone"
fi

if [ "$PURGE" = 1 ]; then
    rm -f "$KUBECONFIG_FILE" "$GEN_VALUES" "$REALM_FILE" "$SECRETS_ENV" \
          "$TLS_CERT" "$TLS_KEY"
    rm -f "$STATE_DIR"/*.html "$STATE_DIR"/*.txt "$STATE_DIR"/*.body 2>/dev/null || true
    ok "purged $STATE_DIR"
fi

say ""
say "  The ~4.1 GB of images inside the node's containerd went with the cluster."
say "  What stays is ~420 MB in the HOST cache (k3s, k3d-proxy, k3d-tools):"
say "    docker image rm $K3S_IMAGE \\"
say "      ghcr.io/k3d-io/k3d-proxy:${K3D_VERSION#v} ghcr.io/k3d-io/k3d-tools:${K3D_VERSION#v}"
say "  Leaving them saves ~40 s of the next up.sh; the in-cluster pulls (~2 min)"
say "  happen again either way, because a new node has an empty containerd."
